<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();$id=filter_var(input('id'),FILTER_VALIDATE_INT);if(!$id)json_response(false,'Valid hunt ID required',null,422);$s=db()->prepare("SELECT h.*,a.status activation_status FROM hunts h LEFT JOIN hunt_user_activations a ON a.hunt_id=h.id AND a.user_id=? WHERE h.id=? AND h.status='ACTIVE'");$s->execute([$user['id'],$id]);$hunt=$s->fetch();if(!$hunt)json_response(false,'Hunt not found',null,404);$l=db()->prepare("SELECT id,name,address,latitude,longitude,radius_meters,sort_order FROM hunt_locations WHERE hunt_id=? AND status='ACTIVE' ORDER BY sort_order,id");$l->execute([$id]);$v=db()->prepare("SELECT id,location_id,title,video_url,sort_order FROM hunt_videos WHERE hunt_id=? AND status='ACTIVE' ORDER BY sort_order,id");$v->execute([$id]);json_response(true,'Hunt details',['hunt'=>$hunt,'locations'=>$l->fetchAll(),'videos'=>$v->fetchAll()]);
